package io.portfolio.erp.web;
import io.portfolio.erp.domain.UserSession; import io.portfolio.erp.security.RequirePermission; import io.portfolio.erp.service.AssetService; import javax.servlet.http.HttpSession; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller public class AssetController { private final AssetService service; public AssetController(AssetService s){service=s;}
  @RequirePermission("ASSET_VIEW") @GetMapping("/assets") public String list(Model m,@RequestParam(defaultValue="") String keyword){m.addAttribute("keyword",keyword);m.addAttribute("assets",service.search(keyword));return "assets/list";}
  @RequirePermission("ASSET_CHANGE") @GetMapping("/assets/change") public String change(Model m){m.addAttribute("assets",service.search(""));return "assets/change";}
  @RequirePermission("ASSET_CHANGE") @PostMapping("/assets/change") public String change(@RequestParam String assetNo,@RequestParam String department,@RequestParam String owner,@RequestParam String location,@RequestParam String reason,HttpSession s){UserSession u=(UserSession)s.getAttribute("loginUser");long id=service.requestChange(assetNo,department,owner,location,reason,u.getUserId());return "redirect:/assets/change?success="+id;}
  @RequirePermission("ASSET_APPROVE") @GetMapping("/assets/approvals") public String approvals(Model m,@RequestParam(defaultValue="PENDING") String status){m.addAttribute("status",status);m.addAttribute("requests",service.requests(status));return "assets/approvals";}
  @RequirePermission("ASSET_APPROVE") @PostMapping("/assets/approvals/{id}") public String decide(@PathVariable long id,@RequestParam String action,HttpSession s){UserSession u=(UserSession)s.getAttribute("loginUser");service.decide(id,"approve".equals(action),u.getUserId());return "redirect:/assets/approvals";}
  @RequirePermission("ASSET_INSPECT") @GetMapping("/assets/inspection") public String inspectPage(Model m){m.addAttribute("assets",service.search(""));return "assets/inspection";}
  @RequirePermission("ASSET_INSPECT") @PostMapping("/assets/inspection") public String inspect(@RequestParam String assetNo,@RequestParam String result,@RequestParam(defaultValue="") String remark,HttpSession s){UserSession u=(UserSession)s.getAttribute("loginUser");service.inspect(assetNo,result,remark,u.getUserId());return "redirect:/assets/inspection?success=1";}
}
